def f(N: int, M: int, edges: List[Tuple[int, int]]):
    '''
    N: an integer
    M: an integer
    edges: a list of tuples, where each tuple contains two integers
    '''
    adj = {i: [] for i in range(1, N+1)}
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)
    visited = [False] * (N+1)
    def dfs(node):
        stack, res = [node], []
        while stack:
            node = stack.pop()
            if not visited[node]:
                visited[node] = True
                res.append(node)
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        stack.append(neighbor)
        return res
    res = []
    for i in range(1, N+1):
        if not visited[i]:
            res.append(dfs(i))
    res.sort(key=len)
    return len(res[-1])
